"""A detector for the words that link a subject to its predicate or complement.

The component fires on forms of the verb 'be' (is, are, was, were, be, been, being) and on the
preposition 'of', and on their foreign equivalents (est, sont, ist, de, di...). Each form gets a
typical activation. A copula after an expletive or demonstrative subject ('there is', 'this is',
'what is') is weak. 'of' after 'out', 'instance', 'because' or 'instead' is weak ('out of').
Negation gets a moderate value, higher right after a copula ('is not'), and frequency adverbs
('often', 'typically') a moderate value. Other prepositions are slightly negative. Everything
else is 0. The program looks only at the previous token, not at the rest of the sentence, so it
misses much of the spread within each word (for example, copulas after nouns vs. after pronouns).
"""

READS = ()

# English forms of 'be', with the typical activation of each.
BE = {" be": 5.8, " been": 6.7, " being": 4.7, " was": 5.8, " were": 6.0, " is": 4.3,
      " are": 4.6, " am": 2.2, "'m": 2.6, "'re": 2.8, "’re": 3.0, "’m": 3.1}
# 'of', and foreign copulas and 'of'-words.
OF = {" of": 4.1, " Of": 2.7, " OF": 3.0, " être": 5.5, " été": 5.6, " essere": 4.9, " sont": 3.5,
      " est": 2.0, " è": 2.2, " ser": 2.0, " ist": 1.2, " são": 4.6, " быть": 2.7, " de": 2.1,
      " di": 1.7, " del": 1.1, " des": 0.7, " van": 2.8, " của": 2.6}
# Expletive or demonstrative subjects, after which a copula is weak.
WEAK_SUBJECT = {"there", "There", " there", " There", "here", "Here", " here", " Here", "this",
                "This", " this", " This", "what", "What", " what", " What", "why", "Why", " why",
                " Why", "how", "How", " how", " How"}
# Fixed phrases in which 'of' is weak.
WEAK_OF_BEFORE = {" out", " instance", " because", " instead"}
FREQ_ADVERBS = {" often", " usually", " typically", " originally", " commonly", " sometimes",
                " frequently", " currently", " generally", " normally"}
BE_BEFORE_NOT = {" is", " are", " was", " were", " be", " been", " am", "'m"}
# Other prepositions sit slightly below zero.
PREPOSITIONS = {" in", " for", " on", " from", " by", " with", " at", " that", " as", " to"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    if tok in BE:
        value = 2.5 if prev in WEAK_SUBJECT else BE[tok]
    elif tok in OF:
        value = 0.8 if prev in WEAK_OF_BEFORE else OF[tok]
    elif tok == " not":
        value = 3.5 if prev in BE_BEFORE_NOT else 1.2
    elif tok in FREQ_ADVERBS:
        value = 1.8
    elif tok in PREPOSITIONS:
        value = -0.3
    else:
        value = 0.0
    return carry, float(value)

"""Sentence-end detector for layers.15.mlp.down_proj, component 261.

What it does: the component fires on the full stop (also ?, !, 。 and the same marks
followed by closing quotes or brackets, such as `).` or `".`) that closes a sentence of
ordinary prose. It is near zero everywhere else, slightly negative on commas and colons.

How strong a sentence end is:
- the word before it: a regular lower-case word (`... the model.`) gives the most;
  a capitalised word (`... Dr.`, `... Paris.`) less; a digit, a single letter (an initial
  or `J.`) or another symbol less still; a sentence end right after another mark gives
  almost nothing;
- the form of the token: a plain mark is full strength, a mark glued to a blank line
  (`.\\n\\n`) about half, a mark glued to a single newline (`.\\n`) almost nothing;
- the length of the sentence so far: it grows over the first ~25 words, then stays;
- exclamation marks count half, an ellipsis nothing;
- inside an assistant turn of a chat transcript (`<|im_start|>assistant ... <|im_end|>`)
  sentence ends fire about twice as strongly.

The constants are the averages of the component's own activations on sampled training
text, rounded to readable values. Everything the program needs is in the token strings
of the prefix and a small carry: the tokens since the last sentence end and whether an
assistant turn is open, both reset at each document boundary.
"""

READS = ()

CLOSERS = ')]}"\'”’»`*>'
SENTENCE_END = '.?!。？！'


def _core(token):
    """The token's text without trailing spaces and closing quotes or brackets."""
    s = token.rstrip()
    while s and s[-1] in CLOSERS:
        s = s[:-1]
    return s


def _word_strength(prev):
    """How strongly the word before a full stop makes it a sentence end."""
    if prev.islower() and prev.isalpha():
        return 2.3  # a regular word: "... the model."
    if prev.isalpha() and prev[:1].isupper() and len(prev) > 1:
        return 1.6  # a capitalised word: "... Paris."
    if prev and prev[-1] in SENTENCE_END:
        return 0.12  # another mark: "?." or "..."
    return 1.15  # digit, single letter (initial, "J."), symbol


def step(carry, prefix, upstream):
    # carry: (tokens since the last sentence end, inside an assistant turn)
    n, in_reply = (0, False) if carry is None else carry
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        n, in_reply = 0, False

    tok = prefix.token_strings[-1]
    core = _core(tok)
    is_end = bool(core) and core[-1] in SENTENCE_END
    value = 0.0
    if is_end:
        prev = _core(prefix.token_strings[-2]).strip() if len(prefix.token_ids) > 1 else ""
        value = _word_strength(prev)
        if tok.endswith("\n\n"):
            value *= 0.5
        elif tok.endswith("\n"):
            value *= 0.15
        if core.endswith("!") or core.endswith("！"):
            value *= 0.5
        if core.endswith(".."):
            value = 0.0
        value *= 0.55 + 0.45 * min(n, 25) / 25  # longer sentences fire more
        if in_reply:
            value *= 2.0
    elif tok.strip() == ",":
        value = -0.2
    elif tok.strip() == ":":
        value = -0.3

    if tok == "<|im_start|>":
        in_reply = False
    elif tok == "assistant" and len(prefix.token_strings) > 1 and prefix.token_strings[-2] == "<|im_start|>":
        in_reply = True
    elif tok == "<|im_end|>":
        in_reply = False
    return (0 if is_end else n + 1, in_reply), value

"""Layer 15 MLP down_proj, component 279: a weak feature on the word "of".

Plain-terms summary: this component is mostly silent. Its activation is large
and noisy on a few tokens, and nearly all of that is on " of". Its size depends on
the word just before " of":
  - partitive / quantity heads ("one of", "some of", "all of", "most of") push
    it slightly negative;
  - heads that name an organisation, place or state ("University of",
    "country of", "Republic of", "State of") push it clearly positive;
  - any other "of" pushes it a little positive.
Every other token predicts 0. Predictions use the sign and rough size of these
class means; the large within-class spread is not modelled.
"""

import wordnet

READS = ()

PARTITIVE = {
    "one", "some", "all", "each", "most", "any", "many", "several",
    "none", "few", "both", "lot", "kind", "type", "types", "series", "variety",
}
ENTITY_CATEGORIES = {"noun.group", "noun.location", "noun.state"}

PARTITIVE_VALUE = -0.36  # mean activation after a partitive head
ENTITY_VALUE = 0.52      # mean after an organisation / place / state noun
OTHER_OF_VALUE = 0.30    # mean after any other word


def _head_class(word):
    word = word.strip().lower()
    if word in PARTITIVE:
        return "partitive"
    cats = wordnet.categories(word) if word.isalpha() else frozenset()
    if cats & ENTITY_CATEGORIES:
        return "entity"
    return "other"


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.token_strings[-1] != " of":
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cls = _head_class(prefix.token_strings[-2])
    value = {
        "partitive": PARTITIVE_VALUE,
        "entity": ENTITY_VALUE,
        "other": OTHER_OF_VALUE,
    }[cls]
    return carry, value

"""Layer-15 MLP down_proj, component 280 of Qwen3-1.7B: a word-cue program.

What the component does: it writes a strongly negative value at words after which the
model expects a bare verb or participle to come next. Those are modals (should, might,
must, can, will ...), negations (not, never, n't), infinitival 'to' (need to, want to,
going to), forms of be, have and do, subject pronouns (I, you, it, they ...), wh-words
and relative pronouns (what, why, who, which, that), and adverbs that sit between an
auxiliary and its verb (has always been, will probably). Its value is near zero on nouns,
articles and most prepositions. It is mildly positive on punctuation and on
sentence-opening connectives (However, Thus, Therefore ...).

This program reads only the current word, and for 'to' the word before it. The numbers
are typical activations per word type, fitted on training text. It does not model the
model's internals and does not look ahead to the next word, so it misses the part of the
activation that depends on what the verb turns out to be.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Strongest cues: the stronger the value, the more firmly a bare verb is expected next.
VERB_CUES = {
    "should": -7.0, "might": -6.5, "must": -6.2, "could": -6.1, "may": -5.8, "would": -5.5,
    "cannot": -6.5, "can": -4.9, "will": -4.9, "shall": -4.8, "'ll": -5.5, "'d": -4.3,
    "not": -5.0, "never": -6.3, "ever": -4.4, "n't": -6.4, "'t": -6.4,
    "be": -4.0, "been": -5.1, "being": -3.8, "was": -4.4, "were": -4.6, "is": -3.5,
    "are": -3.6, "am": -3.0, "does": -4.1, "did": -3.8, "do": -1.7, "had": -2.8,
    "has": -2.5, "have": -2.0, "'ve": -4.4, "'s": -1.2, "'re": -3.7,
}
INFINITIVE_VERBS = {  # words usually followed by 'to' + a verb
    "want", "wanted", "need", "needed", "going", "has", "have", "had", "seem", "seems",
    "seemed", "supposed", "likely", "able", "allowed", "intended", "expected", "meant",
    "used", "tend", "tends", "try", "tried", "decided", "ought", "how",
}
PRONOUNS = {"i": -2.4, "you": -2.7, "we": -2.4, "they": -3.3, "he": -2.6, "she": -2.9, "it": -2.6}
# Relative pronouns and wh-words, which come before a verb in questions and clauses
WH_WORDS = {"who": -4.5, "which": -2.0, "that": -1.8, "what": -2.5, "when": -1.8, "why": -3.0,
            "how": -3.0}
ADVERBS = {  # adverbs between an auxiliary and its verb: "has always been", "will probably"
    "always", "often", "already", "still", "probably", "also", "usually", "really",
    "frequently", "rarely", "necessarily", "merely", "maybe", "originally", "even", "only",
    "just", "eventually", "completely", "easily", "surely",
}
OTHER_CUES = {"by": -1.7, "if": -1.6}
CONNECTIVES = {  # sentence-opening transitions, mildly positive
    "however", "thus", "therefore", "furthermore", "moreover", "additionally", "finally",
    "hence", "instead", "alternatively", "hmm", "wait",
}
PUNCTUATION = {",", ".", ":", "(", "\n", " "}


def word(token: str) -> str:
    return token.strip().replace("’", "'").lower()


def step(carry, prefix, upstream: Mapping):
    raw = prefix.token_strings[-1]
    w = word(raw)
    if w == "to":
        before = word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
        value = -4.7 if before in INFINITIVE_VERBS else -1.9
    elif w in VERB_CUES:
        value = VERB_CUES[w]
    elif w in PRONOUNS:
        value = PRONOUNS[w]
    elif w in WH_WORDS:
        value = WH_WORDS[w]
    elif w in ADVERBS:
        value = -3.0
    elif w in OTHER_CUES:
        value = OTHER_CUES[w]
    elif w in CONNECTIVES:
        value = 1.1
    elif raw in PUNCTUATION:
        value = 0.25
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP hidden unit 289 (the down_proj component 289): a contrast detector.

What it responds to, in plain terms
- Strongly positive on connectives that set up a contrast or concession: "but",
  "yet", "though", "although", "however", and their translations. It is largest
  when "but" follows an adjective, as in "tough but good", "harsh, but not".
- Moderately positive on words that qualify a clause, "also", "even", "still",
  "just", "only", "too", and on "not" after an adverb ("but also", "not just").
- On "and" and "or": positive when they join predicates or descriptions (after a
  verb or an adjective: "both shocked and intrigued"), negative when they join
  nouns, list items, or code and formulas ("status, baseline levels, and ...").
- Weakly positive on subject pronouns and copulas ("it", "they", "is", "are").
- Ordinary tokens get a small lift when a contrast or comparison word ("both",
  "than", "not", "if", "as") appears in the few tokens before them.
- Everywhere else it predicts 0. Most of its activation is small, context-
  dependent noise around 0, which no short rule captures; this program captures
  the large, readable pattern only.

The numbers are least-squares weights fit on about 8k training rows, rounded.
"""

from collections.abc import Mapping

import wordnet

READS: tuple[str, ...] = ()

CONTRAST = {
    "but", "yet", "though", "although", "however",
    "mais", "aber", "pero", "ale", "mas", "doch", "но", "但", "但是", "而且", "却", "又", "而", "并",
}
QUALIFIER = {"also", "even", "still", "just", "only", "too", "not"}
CONJUNCTION = {"and", "or", "和", "或", "、", "&&", "||"}
PRONOUN_COPULA = {"it", "they", "its", "their", "is", "are", "be", "was", "were"}
FRAME = {
    "but", "not", "than", "rather", "both", "either", "neither", "nor", "if", "though",
    "while", "as", "more", "however", "yet", "also", "only", "just", "even", "whether",
}


def _word(token: str) -> str:
    return token.strip().lower()


def _pos(token: str) -> str:
    """The word class of a token, by WordNet: adjective, adverb, noun or verb."""
    word = _word(token)
    if not word.isalpha():
        return "other"
    parts = wordnet.parts_of_speech(word)
    for name in ("adjective", "adverb", "noun", "verb"):
        if name in parts:
            return name
    return "other"


def step(carry, prefix, upstream: Mapping):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _pos(prefix.token_strings[-2]) if same_doc else "other"
    # A contrast or comparison word in the last few tokens of the same document
    # lifts ordinary tokens a little.
    recent = range(max(0, len(prefix.token_strings) - 5), len(prefix.token_strings) - 1)
    framed = any(
        _word(prefix.token_strings[j]) in FRAME and prefix.document_ids[j] == prefix.document_ids[-1]
        for j in recent
    )
    value = 0.25 if framed else 0.0
    if word in CONTRAST:
        value += 3.1
        if prev == "adjective":
            value += 1.2
    elif word in QUALIFIER:
        value += 1.1
        if word == "not" and prev == "adverb":
            value += 2.2
    elif word in CONJUNCTION:
        if prev == "verb":
            value += 1.4
        elif prev in ("adjective", "adverb"):
            value += 0.5
        else:
            value -= 0.2
    elif word in PRONOUN_COPULA:
        value += 0.2
    return carry, float(value)

"""Layer 15 MLP hidden unit 290 (its down_proj write), as a rule-based predictor.

What it responds to: the tokens where a new body or definition is about to start.
  * a copula (" is", " was", ...) right after a closing parenthesis, as in
    "Name (born 1961) is a ...": a description is about to follow (strongest);
  * an opening brace "{", which starts a function or block body (e.g. `int f() {`);
  * a line break that ends with ":" or "(", as in `def f():` and `CREATE TABLE t (`;
  * the indentation that starts the first line of a body (after such a line);
  * an escaped "\\n" inside code strings, and ordinary line breaks (weak).
Everything else, including most words, predicts about 0 (its mean is -0.02).
The values are the average activation of each group, measured on training text.
The groups explain only a few percent of the variance: most of the
component's activity is not captured by surface rules.
"""

READS = ()

COPULAS = {" is", " was", " are", " were"}
OPENER_ENDS = (":", "(")
GROUP_VALUE = {
    "copula_after_paren": 3.0,
    "brace": 1.3,
    "opener_newline": 2.0,
    "body_indent": 1.3,
    "escaped_newline": 0.8,
    "newline": 0.2,
}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    new_doc = len(toks) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    prev = "" if new_doc else toks[-2]
    # carry: last non-space character, the character that ended the previous line,
    # and whether only spaces have been seen since the last line break
    last, line_end, at_line_start = ("", "", True) if (carry is None or new_doc) else carry
    stripped = cur.strip()
    if cur in COPULAS:
        group = "copula_after_paren" if prev.rstrip().endswith(")") else None
    elif "{" in cur:
        group = "brace"
    elif "\n" in cur and stripped.endswith(OPENER_ENDS):
        group = "opener_newline"
    elif stripped == "" and cur != "" and at_line_start and line_end in (":", "{", "("):
        group = "body_indent"
    elif cur == "n" and prev.endswith("\\"):
        group = "escaped_newline"
    elif "\n" in cur:
        group = "newline"
    else:
        group = None
    value = GROUP_VALUE.get(group, 0.0)
    # update the line state with this token
    if "\n" in cur:
        line_end = last
        at_line_start = stripped == ""
    else:
        at_line_start = at_line_start and stripped == ""
    if stripped:
        last = stripped[-1]
    return (last, line_end, at_line_start), value

"""Layer 15 MLP down_proj, component 302: a weak, mostly negative word-class signal.

What it does: the component's activation is usually near zero, but it is pulled
negative on words that open a noun phrase or a clause, where a noun, verb or
object is expected next: possessive determiners ("his", "their", "your"), personal
pronouns ("I", "he", "you"), and opening quotation marks. It is slightly positive
on auxiliaries and negations ("not", "can", "will", "have"), which are followed by
a verb. Everything else gets the baseline value.

Why it is only a rough description: token identity explains very little of this
component's variance (a held-out bigram table gets R^2 of about 0.02). Its large
swings (down to about -20 and up to about +8) depend on context that this program
does not see. The values below are the mean activation of each word class, fitted
on 4096 training rows. The program captures about 1% of the variance.
"""

READS = ()

POSSESSIVE = {"his", "their", "her", "my", "your", "our", "its"}
PRONOUN = {"I", "you", "we", "he", "she", "they", "me", "us", "him", "them", "it"}
OPEN_QUOTE = {'"', "“", "「"}
TO = {"to"}
PREPOSITION = {"of", "with", "for", "about", "in", "on", "by", "from", "after", "at"}
AUX_OR_NEG = {"not", "can", "will", "would", "could", "should", "may", "have", "has",
              "had", "am", "is", "are", "was", "be", "'t", "n't", "’t", "'m"}

# Mean activation per word class (fitted on training rows); other words: +0.03
MEAN = {
    "possessive": -0.67,
    "pronoun": -0.27,
    "quote": -0.40,
    "to": -0.05,
    "preposition": -0.01,
    "aux_or_neg": 0.09,
    "other": 0.03,
}


def word_class(word):
    if word in POSSESSIVE:
        return "possessive"
    if word in PRONOUN:
        return "pronoun"
    if word in OPEN_QUOTE:
        return "quote"
    if word in TO:
        return "to"
    if word in PREPOSITION:
        return "preposition"
    if word in AUX_OR_NEG:
        return "aux_or_neg"
    return "other"


def step(carry, prefix, upstream):
    # The newest token, decoded alone, with its surrounding spaces removed.
    word = prefix.token_strings[prefix.position].strip()
    return carry, MEAN[word_class(word)]

"""Reminiscence about a past time period: a negative-going feature.

Strongly negative on words that place a memory or an event in a remembered past period
(remember, childhood, kid, during, early, time, era, ago, years ...), on "was/were" in a
clause about a person's own past ("when I was"), and on digits of a year written after
"the" or "in" (the 1970s, in 1961). Everything else is near zero. The output is scaled
down, since most of the activation is not explained by these cues.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

PAST_WORDS = {
    "remember": -3.0, "childhood": -3.0, "kid": -2.0, "child": -1.5, "young": -1.0,
    "during": -1.5, "early": -1.5, "time": -1.0, "era": -1.5, "days": -1.0, "years": -0.6,
    "ago": -1.5, "past": -1.0, "once": -1.0, "originally": -1.5, "birth": -1.0, "lived": -1.0,
    "centuries": -1.5, "decades": -1.5, "period": -1.5,
}
PAST_BE = {"was": -0.7, "were": -0.5}
PERSON_BEFORE = {"i", "he", "she", "when"}
PAST_CHARS = set("当时曾以前年時期代")
SCALE = 0.5


def is_year_digit(texts):
    """True for a digit that ends a run of digits starting with 1 or 2, after 'the' or 'in'."""
    k = 0
    i = len(texts) - 1
    while i >= 0 and len(texts[i]) == 1 and texts[i].isdigit():
        k += 1
        i -= 1
    if k == 0 or k > 4 or i < 0 or texts[i + 1] not in ("1", "2"):
        return False
    return i >= 0 and texts[i].lower() in ("the", "in")


def step(carry, prefix, upstream: Mapping):
    texts = [t.strip() for t in prefix.token_strings]
    word = texts[-1].lower()
    before = texts[-2].lower() if len(texts) > 1 else ""
    if word in PAST_WORDS:
        value = PAST_WORDS[word]
    elif word in PAST_BE:
        value = PAST_BE[word] * (2.0 if before in PERSON_BEFORE else 1.0)
    elif any(ch in PAST_CHARS for ch in word):
        value = -2.0
    elif len(word) == 1 and word.isdigit() and is_year_digit(texts):
        value = -1.0
    else:
        value = 0.0
    return carry, SCALE * value
